import { useEffect, useRef, useState } from 'react';

import { JsonCacheContextValue } from 'contexts/JsonCache';
import {
  usePageCacheBaseState,
  usePageCacheLoadingGate,
  useResolvedPageHash,
} from 'hooks/usePageCache/shared';
import { BffResponse } from 'services';
import { PageCacheService } from 'services/PageCacheService/PageCacheService';
import { compressToBase64, decompressFromBase64 } from 'utils/compression';

const CACHE_VERSION = '1';

export interface CachedViewResponses {
  version: string;
  views: Record<string, BffResponse>;
}

export interface UsePageCacheJsonProps {
  pageName: string;
  enabled?: boolean;
  isPageReady?: boolean;
  contextRef?: React.MutableRefObject<JsonCacheContextValue | null>;
}

export interface UsePageCacheJsonResult {
  isCacheChecking: boolean;
  isCacheHit: boolean;
  isStaleHit: boolean;
  shouldRevalidate: boolean;
  cachedViews: Record<string, BffResponse> | null;
}

export const usePageCacheJson = ({
  pageName,
  enabled = true,
  isPageReady = false,
  contextRef,
}: UsePageCacheJsonProps): UsePageCacheJsonResult => {
  const {
    isCacheChecking,
    isCacheHit,
    isStaleHit,
    shouldRevalidate,
    setIsCacheChecking,
    setIsCacheHit,
    setIsStaleHit,
    setShouldRevalidate,
    checkedHashRef,
    abortControllerRef,
  } = usePageCacheBaseState();

  const { pageHash } = useResolvedPageHash(pageName);

  const [cachedViews, setCachedViews] = useState<Record<
    string,
    BffResponse
  > | null>(null);

  useEffect(() => {
    if (!enabled || !pageHash || pageHash === checkedHashRef.current) return;

    checkedHashRef.current = pageHash;

    abortControllerRef.current?.abort();
    const abortController = new AbortController();
    abortControllerRef.current = abortController;

    setIsCacheChecking(true);
    setCachedViews(null);
    setIsCacheHit(false);
    setIsStaleHit(false);
    setShouldRevalidate(false);

    PageCacheService.getInstance()
      .get(pageName, pageHash, abortController.signal)
      .then(async (result) => {
        if (abortController.signal.aborted) return;

        if (result?.html) {
          try {
            const json = decompressFromBase64(result.html);
            const parsed: CachedViewResponses = JSON.parse(json);

            if (parsed.version === CACHE_VERSION && parsed.views) {
              setCachedViews(parsed.views);
              setIsCacheHit(true);
              setIsStaleHit(!!result.isStale);
              setShouldRevalidate(!!result.shouldRevalidate);
            }
          } catch {
            // corrupted cache — treat as miss
          }
        }

        setIsCacheChecking(false);
      })
      .catch(() => {
        if (!abortController.signal.aborted) {
          setIsCacheChecking(false);
        }
      });

    return () => {
      abortController.abort();
    };
  }, [enabled, pageName, pageHash]);

  const submittedHashRef = useRef<string>('');
  const wasLoadingRef = usePageCacheLoadingGate(
    isPageReady,
    isCacheChecking,
    isCacheHit,
    isStaleHit,
    shouldRevalidate,
  );

  useEffect(() => {
    if (!enabled || !isPageReady || !pageHash || isCacheChecking) return;

    const shouldSubmitByState = !isCacheHit || (isStaleHit && shouldRevalidate);
    if (!shouldSubmitByState) return;
    if (!wasLoadingRef.current) return;
    if (submittedHashRef.current === pageHash) return;

    const ctx = contextRef?.current;
    if (!ctx) return;

    submittedHashRef.current = pageHash;

    const submitCache = async () => {
      try {
        const views = ctx.getAllViews();
        if (Object.keys(views).length === 0) return;

        const payload: CachedViewResponses = {
          version: CACHE_VERSION,
          views,
        };

        const serialized = JSON.stringify(payload);
        const compressed = compressToBase64(serialized);

        await PageCacheService.getInstance().set(
          pageName,
          pageHash,
          compressed,
        );
      } catch (error) {
        console.error('Failed to submit JSON cache:', error);
      }
    };

    submitCache();
  }, [
    enabled,
    isPageReady,
    pageName,
    pageHash,
    isCacheHit,
    isStaleHit,
    shouldRevalidate,
    isCacheChecking,
    contextRef,
    wasLoadingRef,
  ]);

  return {
    isCacheChecking,
    isCacheHit,
    isStaleHit,
    shouldRevalidate,
    cachedViews,
  };
};
